create index if not exists idx_map_discovery_cache_cell on public.map_discovery_cache(cell_lat,cell_lng); create index if not exists idx_locations_source_external on public.locations(source_dataset,source_external_id); create or replace function public.claim_map_discovery_cell(p_cell_lat numeric,p_cell_lng numeric,p_radius_m integer default 10000,p_lease_minutes integer default 10) returns table(should_refresh boolean,lease_until timestamptz) language plpgsql security definer set search_path=public as $$ declare v_refreshed timestamptz; v_lease timestamptz; begin select refreshed_at, map_discovery_cache.lease_until into v_refreshed,v_lease from public.map_discovery_cache where cell_lat=round(p_cell_lat,2) and cell_lng=round(p_cell_lng,2) and radius_m=p_radius_m limit 1; if v_refreshed is not null and v_refreshed > now() - interval '6 hours' and (v_lease is null or v_lease <= now()) then return query select false, v_lease; return; end if; v_lease:=now() + make_interval(mins=>p_lease_minutes); insert into public.map_discovery_cache(cell_lat,cell_lng,radius_m,refreshed_at,discovered_count,imported_count,updated_count,lease_until) values(round(p_cell_lat,2),round(p_cell_lng,2),p_radius_m,coalesce(v_refreshed,'epoch'),0,0,0,v_lease) on conflict (cell_lat,cell_lng,radius_m) do update set lease_until=excluded.lease_until returning true,lease_until into should_refresh,lease_until; end; $$;
